/* Ironlog — the rest timer: start, tick, the bar under the set, the adjust
   buttons and the notification. Split out of workout.js (ROADMAP E17 phase 5)
   so erasing the log can stop it without importing the workout screen. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { $, Cue, esc, fmtSec } from './core.js';
import { save } from './database.js';
import { exFull } from './exercises.js';
import { toast } from './kit.js';
import { S } from './state.js';
import { restFor } from './training.js';
/* end imports */

/* ---------------- rest timer ---------------- */
export let restIv = null;
export function startRest(ei, s) {
  const a = S.active;
  const e = a && a.exercises[ei];
  if (!e || S.settings.restAuto === false) return;
  const len = restFor(e, s);
  a.rest = { endAt: Date.now() + len * 1000, len, ei, name: exFull(e) };
  Cue.unlock();               // the tick is the gesture; the end beep needs the context awake
  restLoop();
}
export function stopRest() {
  if (S.active) delete S.active.rest;
  clearInterval(restIv); restIv = null;
  const host = $('#restHost');
  if (host) host.innerHTML = '';
}
export function restLoop() {
  clearInterval(restIv);
  restIv = setInterval(restTick, 250);
  restTick();
}
function restTick() {
  const r = S.active && S.active.rest;
  if (!r) { clearInterval(restIv); restIv = null; return; }
  const left = (r.endAt - Date.now()) / 1000;
  const warnAt = +S.settings.restWarn || 0;
  // a warning only makes sense on a rest meaningfully longer than it
  if (!r.warned && warnAt > 0 && r.len > warnAt + 5 && left <= warnAt && left > 0) {
    r.warned = true;
    Cue.beep(800, 90); Cue.beep(800, 90, 0.18); Cue.buzz(80);
  }
  if (left <= 0 && !r.alerted) {
    r.alerted = true;
    /* Coming back to the app long after rest ran out shouldn't set it off. */
    if (left > -30) {
      Cue.done();
      if (document.visibilityState === 'hidden') restNotify(r);
      else toast(`Rest over — ${r.name}`, 'green');
    }
    save();
  }
  if (left < -600) { stopRest(); save(); return; }    // ten minutes over: nobody is resting now
  paintRest();
}
export function restBarHtml() {
  const r = S.active && S.active.rest;
  if (!r) return '';
  return `<div class="restbar" id="restBar">
    <div class="grow"><div class="eyebrow">Rest · ${esc(r.name)}</div><div class="rc" id="restClock"></div></div>
    <button class="btn xs ghost" data-rest="-15">−15</button>
    <button class="btn xs ghost" data-rest="15">+15</button>
    <button class="btn xs ghost" data-rest="skip">Skip</button>
  </div>`;
}
/* Only the clock text changes per tick; the buttons are built once. */
export function paintRest() {
  const r = S.active && S.active.rest;
  const host = $('#restHost');
  if (!host) return;
  if (!r) { host.innerHTML = ''; return; }
  if (!$('#restBar', host)) host.innerHTML = restBarHtml();
  const left = (r.endAt - Date.now()) / 1000;
  $('#restClock', host).textContent = left > 0 ? fmtSec(Math.ceil(left)) : `+${fmtSec(Math.floor(-left))}`;
  $('#restBar', host).classList.toggle('over', left <= 0);
}
/* ±15 s moves this rest and becomes this exercise's rest for the session. */
export function adjustRest(d) {
  const r = S.active && S.active.rest;
  if (!r) return;
  const now = Date.now();
  r.endAt = Math.max(now, r.endAt + d * 1000);
  r.len = Math.max(15, r.len + d);
  const e = S.active.exercises[r.ei];
  if (e) e.rest = r.len;
  const left = (r.endAt - now) / 1000;
  if (left > 0) r.alerted = false;
  if (left > (+S.settings.restWarn || 0)) r.warned = false;
  save(); paintRest();
}
/* Best effort, as the roadmap asks: a page in the background may be frozen
   before the moment comes, and without permission there is nothing to show. */
function restNotify(r) {
  try {
    if (!('Notification' in window) || Notification.permission !== 'granted' || !navigator.serviceWorker) return;
    navigator.serviceWorker.ready.then(reg => reg.showNotification('Rest over', {
      body: `Next set — ${r.name}`, tag: 'ironlog-rest', renotify: true, icon: 'icon-192.png',
      ...(S.settings.vibrate !== false ? { vibrate: [220, 120, 220] } : {}),
    })).catch(() => {});
  } catch (e) { /* notifications unavailable */ }
}
